// Run once for all items. Input: one { groupJid, messageId } item per test destination.
const baseUrl = 'https://evolution-forward-test.example.com';
const instanceName = 'forward-lab';

return $input.all().map((item, index) => {
  const { groupJid, messageId } = item.json;
  if (typeof groupJid !== 'string' || !/^[0-9]+(?:-[0-9]+)?@g\.us$/.test(groupJid)) {
    throw new Error('groupJid must be the full test group JID ending in @g.us');
  }
  if (typeof messageId !== 'string' || !/^\S{1,200}$/.test(messageId)) {
    throw new Error('messageId must come from data.key.id in the test instance webhook');
  }
  return {
    json: {
      url: baseUrl.replace(/\/$/, '') + '/message/forwardMessage/' + encodeURIComponent(instanceName),
      body: { number: groupJid, messageId },
    },
    pairedItem: { item: index },
  };
});
